    bibe: BasicBIBE,
    pk: PublicKey,
    ciphertexts: Sequence[Tuple[Any, Ciphertext]],
    batch_key: Any,
    digest: Any,
    identities: Sequence[Any],
    batch_label: Any,
) -> List[Any]:
