    signature = timed("-----sign-----\n", lambda: bls.sign(secret_key, message))
    print(f"消息：{message}")
    print(f"签名 sigma=H(m)^x={short(signature)}")

    ok = timed("-----verify-----\n", lambda: bls.verify(public_key, message, signature))
